"""Solvers for SubsetSum and Sat, from the definitions.

subset_sum_solve: exact DP over reachable sums (correct, exponential-ish but
fine for small tests).
sat_solve: DPLL with unit propagation (exact).
"""


def subset_sum_solve(instance):
    numbers = instance["numbers"]
    t = instance["target"]
    if t < 0:
        return False
    reachable = {0}
    for a in numbers:
        reachable |= {r + a for r in reachable}
    return t in reachable


def _simplify(clauses, assignment):
    """Return simplified clauses given a partial assignment, or None if
    unsatisfiable.  assignment: dict var->bool."""
    out = []
    for clause in clauses:
        new_clause = []
        satisfied = False
        for lit in clause:
            v = abs(lit)
            if v in assignment:
                val = assignment[v]
                if (lit > 0 and val) or (lit < 0 and not val):
                    satisfied = True
                    break
            else:
                new_clause.append(lit)
        if satisfied:
            continue
        if not new_clause:
            return None  # empty clause -> unsat
        out.append(new_clause)
    return out


def sat_solve(instance):
    m = instance["num_vars"]
    clauses = [list(c) for c in instance["clauses"]]
    # no clauses -> satisfiable
    if not clauses:
        return True
    # DPLL
    assignment = {}

    def dpll(clauses, assignment):
        clauses = _simplify(clauses, assignment)
        if clauses is None:
            return False
        if not clauses:
            return True
        # unit propagation
        while True:
            unit = None
            for clause in clauses:
                if len(clause) == 1:
                    unit = clause[0]
                    break
            if unit is None:
                break
            v = abs(unit)
            val = unit > 0
            if v in assignment:
                if assignment[v] != val:
                    return False
            else:
                assignment = dict(assignment)
                assignment[v] = val
            clauses = _simplify(clauses, assignment)
            if clauses is None:
                return False
            if not clauses:
                return True
        # pure literal elimination
        while True:
            pos = set()
            neg = set()
            for clause in clauses:
                for lit in clause:
                    if lit > 0:
                        pos.add(lit)
                    else:
                        neg.add(-lit)
            pure = None
            for v in pos:
                if v not in neg:
                    pure = v
                    break
            if pure is None:
                for v in neg:
                    if v not in pos:
                        pure = -v
                        break
            if pure is None:
                break
            v = abs(pure)
            assignment = dict(assignment)
            assignment[v] = pure > 0
            clauses = _simplify(clauses, assignment)
            if clauses is None:
                return False
            if not clauses:
                return True
        # choose variable
        v = abs(clauses[0][0])
        for val in (True, False):
            a2 = dict(assignment)
            a2[v] = val
            if dpll(clauses, a2):
                return True
        return False

    return dpll(clauses, assignment)
